<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3';
import BaseLayout from '../../layouts/BaseLayout.vue'; import BaseCard from '../../components/BaseCard.vue'; import FormButton from '../../components/FormButton.vue'; import BadgeState from '../../components/BadgeState.vue';
const props = defineProps<{ badges: { data: { id: string; code: string; status: string; batch_name: string; reserved_station: string | null }[]; total: number; prev_page_url: string | null; next_page_url: string | null }; batches: { id: string; name: string }[]; statuses: string[]; filters: { status?: string; batch?: string; reserved?: string } }>();
const form = useForm({ status: props.filters.status || '', batch: props.filters.batch || '', reserved: props.filters.reserved || '' });
</script>
<template>
<BaseLayout>
<Link href="/espace" class="block min-h-14 underline">Mon espace</Link><h1 class="mb-4 text-display font-bold">Administration · Badges</h1><p class="mb-6">Consultation uniquement. Aucun badge ne peut être attribué, annulé ou modifié depuis cet écran.</p>
<BaseCard><form class="space-y-5" aria-label="Filtrer les badges" @submit.prevent="form.get('/administration/badges')"><label class="block">Statut<select v-model="form.status" class="field"><option value="">Tous les statuts</option><option v-for="status in statuses" :key="status">{{ status }}</option></select></label><label class="block">Lot<select v-model="form.batch" class="field"><option value="">Tous les lots</option><option v-for="batch in batches" :key="batch.id" :value="batch.id">{{ batch.name }}</option></select></label><label class="block">Réservation par poste<select v-model="form.reserved" class="field"><option value="">Tous les badges</option><option value="oui">Réservés à un poste</option><option value="non">Sans poste réservé</option></select></label><p v-for="error in form.errors" :key="error" role="alert">{{ error }}</p><FormButton :busy="form.processing">Filtrer les badges</FormButton></form></BaseCard>
<p class="my-6">{{ badges.total }} badge(s) correspondant aux filtres</p><ol class="grid gap-4 sm:grid-cols-2"><li v-for="badge in badges.data" :key="badge.id"><BaseCard><h2 class="mb-3 text-heading font-bold">{{ badge.code }}</h2><BadgeState :status="badge.status" /><p class="mt-4">{{ badge.batch_name }}</p><p>{{ badge.reserved_station ? `Poste réservé : ${badge.reserved_station}` : 'Sans poste réservé' }}</p></BaseCard></li></ol><p v-if="!badges.data.length">Aucun badge pour ces filtres.</p><nav class="mt-6 flex gap-4"><Link v-if="badges.prev_page_url" :href="badges.prev_page_url" class="action">Précédent</Link><Link v-if="badges.next_page_url" :href="badges.next_page_url" class="action">Suivant</Link></nav>
</BaseLayout>
</template>
